/**
 * Runtime audio-pump policy for LXST calls.
 */
data class AppAudioPolicy (
    /**
     * Bridge callback latency (ms) above which `AppUpdate::AudioWarning`
     * is emitted.
     */
    var `warningLatencyMs`: kotlin.ULong
    , 
    /**
     * Consecutive bridge failures before the pump falls back to
     * null-codec mode.
     */
    var `maxConsecutiveFailures`: kotlin.UInt
    , 
    /**
     * Minimum call quality (0.0–1.0); calls below it auto-close.
     */
    var `minQuality`: kotlin.Double?
    , 
    /**
     * Consecutive low-quality network ticks tolerated before auto-close.
     */
    var `qualityGraceTicks`: kotlin.UInt
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAppAudioPolicy: FfiConverterRustBuffer<AppAudioPolicy> {
    override fun read(buf: ByteBuffer): AppAudioPolicy {
        return AppAudioPolicy(
            FfiConverterULong.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterOptionalDouble.read(buf),
            FfiConverterUInt.read(buf),
        )
    }

    override fun allocationSize(value: AppAudioPolicy) = (
            FfiConverterULong.allocationSize(value.`warningLatencyMs`) +
            FfiConverterUInt.allocationSize(value.`maxConsecutiveFailures`) +
            FfiConverterOptionalDouble.allocationSize(value.`minQuality`) +
            FfiConverterUInt.allocationSize(value.`qualityGraceTicks`)
    )

    override fun write(value: AppAudioPolicy, buf: ByteBuffer) {
            FfiConverterULong.write(value.`warningLatencyMs`, buf)
            FfiConverterUInt.write(value.`maxConsecutiveFailures`, buf)
            FfiConverterOptionalDouble.write(value.`minQuality`, buf)
            FfiConverterUInt.write(value.`qualityGraceTicks`, buf)
    }
}



/**
 * Access control for a hosted shared instance.
 */
data class AppSharedInstanceAccessConfig (
    /**
     * Client names allowed to connect (empty = allow any).
     */
    var `allow`: List<kotlin.String>
    , 
    /**
