    override fun write(value: AppUpdate, buf: ByteBuffer) {
        when(value) {
            is AppUpdate.FullState -> {
                buf.putInt(1)
                FfiConverterTypeAppState.write(value.v1, buf)
                Unit
            }
            is AppUpdate.NodeStatus -> {
                buf.putInt(2)
                FfiConverterTypeNodeStatus.write(value.v1, buf)
