                FfiConverterString.write(value.`destinationHash`, buf)
                Unit
            }
            is AppUpdate.MessageStateChanged -> {
                buf.putInt(24)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterString.write(value.`state`, buf)
                FfiConverterDouble.write(value.`progress`, buf)
                Unit
            }
            is AppUpdate.MessageDuplicate -> {
                buf.putInt(25)
                FfiConverterString.write(value.`hash`, buf)
                Unit
            }
            is AppUpdate.DeliveryReceipt -> {
                buf.putInt(26)
                FfiConverterString.write(value.`hash`, buf)
                Unit
            }
            is AppUpdate.SendFailed -> {
                buf.putInt(27)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is AppUpdate.PaperMessagePacked -> {
                buf.putInt(28)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterString.write(value.`uri`, buf)
                Unit
            }
            is AppUpdate.PropagationTransferChanged -> {
                buf.putInt(29)
                FfiConverterString.write(value.`state`, buf)
                FfiConverterDouble.write(value.`progress`, buf)
                FfiConverterULong.write(value.`size`, buf)
                Unit
            }
            is AppUpdate.CallStateChanged -> {
                buf.putInt(30)
                FfiConverterString.write(value.`callId`, buf)
                FfiConverterString.write(value.`state`, buf)
                Unit
            }
            is AppUpdate.IncomingCall -> {
                buf.putInt(31)
                FfiConverterString.write(value.`callId`, buf)
                FfiConverterString.write(value.`destinationHash`, buf)
                Unit
            }
            is AppUpdate.CallFrames -> {
                buf.putInt(32)
                FfiConverterString.write(value.`callId`, buf)
                FfiConverterString.write(value.`codec`, buf)
                FfiConverterByteArray.write(value.`data`, buf)
                Unit
            }
            is AppUpdate.CallClosed -> {
                buf.putInt(33)
                FfiConverterString.write(value.`callId`, buf)
                Unit
            }
            is AppUpdate.AudioWarning -> {
                buf.putInt(34)
                FfiConverterString.write(value.`callId`, buf)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is AppUpdate.ResourceProgress -> {
                buf.putInt(35)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterString.write(value.`status`, buf)
                FfiConverterDouble.write(value.`progress`, buf)
                Unit
            }
            is AppUpdate.ResourceComplete -> {
                buf.putInt(36)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterOptionalByteArray.write(value.`data`, buf)
                FfiConverterOptionalByteArray.write(value.`metadata`, buf)
                Unit
            }
            is AppUpdate.ResourceFailed -> {
                buf.putInt(37)
                FfiConverterString.write(value.`hash`, buf)
                Unit
            }
            is AppUpdate.DiscoveryUpdated -> {
                buf.putInt(38)
                FfiConverterSequenceTypeDiscoveredInterfaceSummary.write(value.`interfaces`, buf)
                Unit
            }
            is AppUpdate.SharedInstanceClientConnected -> {
                buf.putInt(39)
                FfiConverterString.write(value.`address`, buf)
                Unit
            }
            is AppUpdate.SharedInstanceClientDisconnected -> {
                buf.putInt(40)
                FfiConverterString.write(value.`address`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






