        val len = buf.getInt()
        return List<LinkSummary>(len) {
            FfiConverterTypeLinkSummary.read(buf)
        }
    }

    override fun allocationSize(value: List<LinkSummary>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeLinkSummary.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<LinkSummary>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeLinkSummary.write(it, buf)
        }
    }
}




